/* Standalone driver mimicking fuzz_eval.c: reads a file and evals it
 * as global code, then runs the event loop. */
#include "quickjs.h"
#include "quickjs-libc.h"
#include "cutils.h"
#include "fuzz/fuzz_common.h"

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int interrupt_handler(JSRuntime *rt, void *opaque)
{
    (void)rt; (void)opaque;
    nbinterrupts++;
    return (nbinterrupts > 100);
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        fprintf(stderr, "usage: %s <file.js>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *data = malloc(sz > 0 ? sz : 1);
    size_t n = fread(data, 1, sz, f);
    fclose(f);

    JSRuntime *rt = JS_NewRuntime();
    JSContext *ctx = JS_NewContext(rt);
    JS_SetMemoryLimit(rt, 0x4000000);
    JS_SetMaxStackSize(rt, 0x10000);
    JS_SetModuleLoaderFunc(rt, NULL, js_module_loader, NULL);
    JS_SetInterruptHandler(rt, interrupt_handler, NULL);
    js_std_add_helpers(ctx, 0, NULL);
    js_std_init_handlers(rt);
    js_init_module_std(ctx, "std");
    js_init_module_os(ctx, "os");

    reset_nbinterrupts();
    JSValue val = JS_Eval(ctx, (const char *)data, n, "<none>", JS_EVAL_TYPE_GLOBAL);
    free(data);
    if (!JS_IsException(val)) {
        js_std_loop(ctx);
        JS_FreeValue(ctx, val);
    } else {
        js_std_dump_error(ctx);
    }
    js_std_free_handlers(rt);
    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);
    return 0;
}

