/* Mini coverage-guided fuzzer for quickjs fuzz_eval using gcc trace-pc.
 * Compile quickjs lib with -fsanitize=address -fsanitize-coverage=trace-pc
 * and link this file. Runs each input in a forked child; parent guides
 * mutations by the shared coverage bitmap. */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>

/* quickjs fuzz_eval entry */
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

#define MAP_SIZE (1 << 20)
static uint8_t *cov_map;

void __sanitizer_cov_trace_pc(void)
{
    uintptr_t pc = (uintptr_t)__builtin_return_address(0);
    uint32_t h = (uint32_t)((pc >> 4) ^ (pc >> 15) ^ (pc >> 23));
    cov_map[h & (MAP_SIZE - 1)] = 1;
}

typedef struct {
    uint8_t *data;
    size_t size;
    uint64_t sig;
} CorpusEntry;

#define MAX_CORPUS 20000
static CorpusEntry corpus[MAX_CORPUS];
static int corpus_size = 0;
static int max_len = 8192;

static uint64_t hash_map(void)
{
    uint64_t h = 1469598103934665603ULL;
    /* sample the map */
    for (int i = 0; i < MAP_SIZE; i += 97) {
        h ^= cov_map[i];
        h *= 1099511628211ULL;
    }
    return h;
}

static uint64_t hash_data(const uint8_t *d, size_t n)
{
    uint64_t h = 1469598103934665603ULL;
    for (size_t i = 0; i < n; i++) {
        h ^= d[i];
        h *= 1099511628211ULL;
    }
    return h;
}

static void add_to_corpus(const uint8_t *d, size_t n)
{
    if (corpus_size >= MAX_CORPUS)
        return;
    if (n > max_len)
        n = max_len;
    CorpusEntry *e = &corpus[corpus_size];
    e->data = malloc(n ? n : 1);
    memcpy(e->data, d, n);
    e->size = n;
    e->sig = hash_map();
    corpus_size++;
    if (corpus_size % 50 == 0)
        fprintf(stderr, "[corpus=%d len=%zu]\n", corpus_size, n);
}

static int load_file(const char *path, uint8_t **out, size_t *outn)
{
    FILE *f = fopen(path, "rb");
    if (!f) return -1;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = malloc(sz ? sz : 1);
    size_t n = fread(buf, 1, sz, f);
    fclose(f);
    *out = buf;
    *outn = n;
    return 0;
}

static uint32_t rng_state;
static uint32_t rnd(void)
{
    rng_state = rng_state * 1664525u + 1013904223u;
    return rng_state;
}

static void mutate(uint8_t *buf, size_t *pn)
{
    size_t n = *pn;
    int ops = 1 + rnd() % 8;
    for (int k = 0; k < ops; k++) {
        int op = rnd() % 6;
        if (n == 0) op = 0;
        switch (op) {
        case 0: { /* flip byte */
            buf[rnd() % n] ^= (1u << (rnd() % 8));
            break;
        }
        case 1: { /* set byte */
            buf[rnd() % n] = rnd() & 0xff;
            break;
        }
        case 2: { /* insert byte */
            if (n < max_len) {
                memmove(buf + 1 + (rnd() % (n + 1)), buf, n);
                buf[rnd() % (n + 1)] = "{}[]();,=+-*/.<>\"'`\n "[rnd() % 24];
                n++;
            }
            break;
        }
        case 3: { /* delete byte */
            if (n > 1) {
                size_t p = rnd() % n;
                memmove(buf + p, buf + p + 1, n - p - 1);
                n--;
            }
            break;
        }
        case 4: { /* overwrite with random ascii word */
            static const char *toks[] = {
                "Float16Array", "RegExp.escape", "Math.f16round", "new ",
                "class ", "extends ", "super", "get ", "set ", "static ",
                "async ", "await", "function*", "yield", "=>", "==", "===",
                "0x", "1n", "0n", "[", "]", "{", "}", "(", ")", "=", ".",
                "...", "throw", "try", "catch", "finally", "with", "in",
                "of", "for", "while", "if", "return", "var", "let", "const",
                "import", "export", "Symbol.", "Proxy", "Reflect", "Object.",
                "Array.", "String.", "typed", "new.target", "this", "arguments",
                "delete", "typeof", "instanceof", "void", "??", "?.", "**",
                "\\u", "\\x", "\\n", "\"", "\'", "`", "${", "}", "/*", "*/",
                "//", "0.1", "1e300", "NaN", "Infinity", "-0", "0.5", "1.5",
            };
            size_t p = rnd() % (n + 1);
            const char *t = toks[rnd() % (sizeof(toks) / sizeof(toks[0]))];
            size_t tl = strlen(t);
            if (n + tl < max_len) {
                memmove(buf + p + tl, buf + p, n - p);
                memcpy(buf + p, t, tl);
                n += tl;
            }
            break;
        }
        case 5: { /* duplicate a chunk */
            if (n > 1 && n < max_len - 8) {
                size_t p = rnd() % n;
                size_t l = 1 + rnd() % (n - p);
                if (l > 64) l = 64;
                if (n + l <= max_len) {
                    memmove(buf + p + l, buf + p, n - p);
                    memcpy(buf + p, buf + p + l, l);
                    n += l;
                }
            }
            break;
        }
        }
    }
    *pn = n;
}

int main(int argc, char **argv)
{
    cov_map = mmap(NULL, MAP_SIZE, PROT_READ | PROT_WRITE,
                   MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (cov_map == MAP_FAILED) { perror("mmap"); return 1; }

    rng_state = time(NULL) ^ getpid();
    int seed_count = 0;
    for (int i = 1; i < argc; i++) {
        uint8_t *buf; size_t n;
        if (load_file(argv[i], &buf, &n) == 0) {
            /* run seed to get its coverage signature */
            memset(cov_map, 0, MAP_SIZE);
            pid_t pid = fork();
            if (pid == 0) {
                _exit(LLVMFuzzerTestOneInput(buf, n));
            }
            int st; waitpid(pid, &st, 0);
            add_to_corpus(buf, n);
            seed_count++;
        }
    }
    fprintf(stderr, "seeds=%d\n", seed_count);

    uint8_t *buf = malloc(max_len);
    for (long iter = 0; ; iter++) {
        /* pick a corpus entry */
        CorpusEntry *e = &corpus[rnd() % corpus_size];
        size_t n = e->size;
        memcpy(buf, e->data, n);
        /* occasionally splice with another entry */
        if (corpus_size > 1 && (rnd() % 4) == 0) {
            CorpusEntry *e2 = &corpus[rnd() % corpus_size];
            size_t p = n ? rnd() % n : 0;
            size_t l = e2->size ? rnd() % e2->size : 0;
            if (l > 32) l = 32;
            if (p + l < max_len) {
                memcpy(buf + p, e2->data, l);
                if (p + l > n) n = p + l;
            }
        }
        mutate(buf, &n);

        memset(cov_map, 0, MAP_SIZE);
        pid_t pid = fork();
        if (pid == 0) {
            /* child: run the harness */
            alarm(5);
            _exit(LLVMFuzzerTestOneInput(buf, n));
        }
        int st;
        waitpid(pid, &st, 0);
        if (WIFSIGNALED(st)) {
            fprintf(stderr, "\nCRASH: iter=%ld signal=%d size=%zu\n", iter, WTERMSIG(st), n);
            FILE *f = fopen("/gt/_work/src/crash.js", "wb");
            if (f) { fwrite(buf, 1, n, f); fclose(f); }
            fprintf(stderr, "wrote crash.js\n");
            return 0;
        }
        uint64_t sig = hash_map();
        /* new coverage? */
        int is_new = 1;
        for (int i = 0; i < corpus_size; i++) {
            if (corpus[i].sig == sig) { is_new = 0; break; }
        }
        if (is_new)
            add_to_corpus(buf, n);
        if ((iter % 2000) == 0)
            fprintf(stderr, "iter=%ld corpus=%d\n", iter, corpus_size);
    }
    return 0;
}

